function esc(value){return String(value==null?"":value).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})}
function fmtDate(value){if(!value)return"Not analyzed";var d=new Date(value);return isNaN(d)?"Recently updated":d.toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"})}
function initials(value){return String(value||"P").trim().split(/\s+/).slice(0,2).map(function(s){return s[0]||""}).join("").toUpperCase()}
function toast(message,isError){var box=document.createElement("div");box.className="toast"+(isError?" error":"");box.textContent=message;document.getElementById("toastStack").append(box);setTimeout(function(){box.remove()},4200)}
async function api(path,options){var opts=options||{};opts.credentials="same-origin";opts.headers=opts.headers||{};if(opts.body&&!(opts.body instanceof FormData)&&typeof opts.body!=="string"){opts.headers["content-type"]="application/json";opts.body=JSON.stringify(opts.body)}opts.headers.accept="application/json";var response;try{response=await fetch(path,opts)}catch(error){if(error&&error.name==="AbortError")throw error;throw new Error("Could not reach Procura. Check your connection and try again.")}var type=response.headers.get("content-type")||"";var payload=type.indexOf("application/json")>=0?await response.json():null;if(!response.ok)throw new Error(payload&&payload.error||"The request could not be completed.");return payload}
var pdfJsPromise=null,tesseractScriptPromise=null;
var PDFJS_VERSION="5.7.284",TESSERACT_VERSION="6.0.1";
function uploadStopped(signal){if(signal&&signal.aborted)throw new DOMException("Upload cancelled.","AbortError")}
function setUploadProgress(id,message,percent){var box=document.getElementById(id);if(!box)return;box.classList.remove("hidden");var label=box.querySelector("[data-progress-label]"),bar=box.querySelector("[data-progress-bar]");if(label)label.textContent=message;if(bar)bar.style.width=Math.max(4,Math.min(100,Number(percent)||4))+"%"}
function clearUploadProgress(id){var box=document.getElementById(id);if(box)box.classList.add("hidden")}
function getPdfJs(){if(!pdfJsPromise)pdfJsPromise=import("https://cdn.jsdelivr.net/npm/pdfjs-dist@"+PDFJS_VERSION+"/build/pdf.min.mjs").then(function(lib){lib.GlobalWorkerOptions.workerSrc="https://cdn.jsdelivr.net/npm/pdfjs-dist@"+PDFJS_VERSION+"/build/pdf.worker.min.mjs";return lib}).catch(function(){pdfJsPromise=null;throw new Error("Procura could not load its PDF reader. Check your connection and try again.")});return pdfJsPromise}
function getTesseract(){if(window.Tesseract)return Promise.resolve(window.Tesseract);if(!tesseractScriptPromise)tesseractScriptPromise=new Promise(function(resolve,reject){var script=document.createElement("script");script.src="https://cdn.jsdelivr.net/npm/tesseract.js@"+TESSERACT_VERSION+"/dist/tesseract.min.js";script.async=true;script.onload=function(){window.Tesseract?resolve(window.Tesseract):reject(new Error("OCR engine did not start."))};script.onerror=function(){tesseractScriptPromise=null;reject(new Error("Procura could not load the OCR engine. Check your connection or use a searchable PDF."))};document.head.appendChild(script)});return tesseractScriptPromise}
async function preparePdfFile(file,onProgress,signal){
 if(!/\.pdf$/i.test(file.name||""))return null;
 uploadStopped(signal);
 onProgress("Opening the PDF…",5);
 var pdfjs=await getPdfJs(),buffer=await file.arrayBuffer(),loading=pdfjs.getDocument({data:new Uint8Array(buffer),isEvalSupported:false,verbosity:0}),pdf=null,worker=null;
 state.pdfLoadingTask=loading;
 try{
  try{pdf=await loading.promise}catch(error){if(signal&&signal.aborted)throw new DOMException("Upload cancelled.","AbortError");throw new Error(/password/i.test(error&&error.message||"")?"This PDF is password-protected. Remove its password and try again.":"This PDF could not be opened. Save a fresh PDF and try again.")}
  var pages=[],scanPages=[];
  if(pdf.numPages>300)throw new Error("This PDF has more than 300 pages. Split it into smaller files and try again.");
  for(var n=1;n<=pdf.numPages;n++){
   uploadStopped(signal);
   onProgress("Reading PDF text · page "+n+" of "+pdf.numPages,5+Math.round(n/pdf.numPages*25));
   var page=await pdf.getPage(n),content=await page.getTextContent(),pageText=content.items.map(function(item){return typeof item.str==="string"?item.str:""}).filter(Boolean).join(" ").replace(/\s+/g," ").trim();
   pages.push(pageText);
   if(pageText.length<45)scanPages.push(n);
   page.cleanup();
  }
  if(scanPages.length>60)throw new Error("This PDF has more than 60 scanned pages. Split it into smaller files so OCR can finish reliably.");
  if(scanPages.length){
   onProgress("Preparing secure, in-browser OCR…",32);
   var tesseract=await getTesseract();
   uploadStopped(signal);
   var current=0;
   worker=await tesseract.createWorker("eng",1,{workerPath:"https://cdn.jsdelivr.net/npm/tesseract.js@"+TESSERACT_VERSION+"/dist/worker.min.js",langPath:"https://tessdata.projectnaptha.com/4.0.0",logger:function(info){if(info.status==="recognizing text")onProgress("Reading scanned page "+current+" of "+scanPages.length,35+Math.round(((current-1)+Math.max(0,Math.min(1,info.progress||0)))/scanPages.length*60))}});
   state.ocrWorker=worker;
   if(signal)signal.addEventListener("abort",function(){try{Promise.resolve(worker.terminate()).catch(function(){})}catch(_){}},{once:true});
   for(var i=0;i<scanPages.length;i++){
    uploadStopped(signal);
    current=i+1;
    var pageNumber=scanPages[i],scanPage=await pdf.getPage(pageNumber),viewport=scanPage.getViewport({scale:1.6}),canvas=document.createElement("canvas");
    canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);
    var context=canvas.getContext("2d",{alpha:false});
    if(!context)throw new Error("This browser could not prepare the PDF page for OCR.");
    await scanPage.render({canvasContext:context,viewport:viewport}).promise;
    var recognized=await worker.recognize(canvas);
    pages[pageNumber-1]=[pages[pageNumber-1],String(recognized.data.text||"").trim()].filter(Boolean).join("\n");
    canvas.width=0;canvas.height=0;scanPage.cleanup();
   }
  }
  uploadStopped(signal);
  var combined=pages.filter(Boolean).join("\n").replace(/\n{3,}/g,"\n\n").trim();
  if(combined.length<20)throw new Error("Procura could not read enough text from this PDF. Try a clearer scan or a text-searchable copy.");
  onProgress(scanPages.length?"OCR complete · saving the original PDF and extracted text…":"PDF text ready · saving to your cloud workspace…",98);
  return{text:combined,method:scanPages.length?"ocr":"pdfjs"};
 }finally{
  state.pdfLoadingTask=null;
  if(worker){if(state.ocrWorker===worker)state.ocrWorker=null;try{await worker.terminate()}catch(_){}}
  if(pdf){try{await pdf.destroy()}catch(_){}}else{try{await loading.destroy()}catch(_){}}
 }
}
function stopActiveUpload(){if(state.uploadController){state.uploadController.abort();state.uploadController=null}if(state.ocrWorker){try{Promise.resolve(state.ocrWorker.terminate()).catch(function(){})}catch(_){}state.ocrWorker=null}if(state.pdfLoadingTask){try{Promise.resolve(state.pdfLoadingTask.destroy()).catch(function(){})}catch(_){}state.pdfLoadingTask=null}}
