function selectPreviewStep(step){
 var selected=Math.max(0,Math.min(2,Number(step)||0));
 document.querySelectorAll(".preview-tab").forEach(function(tab){var active=Number(tab.dataset.step)===selected;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",String(active))});
 document.querySelectorAll("[data-preview-panel]").forEach(function(panel){panel.hidden=Number(panel.dataset.previewPanel)!==selected});
}
function attachPreviewMotion(){
 var frame=document.getElementById("previewFrame"),card=document.getElementById("previewCard");
 if(!frame||!card||matchMedia("(prefers-reduced-motion: reduce)").matches)return;
 var floaters=frame.querySelectorAll(".hero-float");
 frame.addEventListener("pointermove",function(e){
  if(e.pointerType==="touch")return;
  var r=frame.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
  card.style.transform="translate3d("+(x*4)+"px,"+(y*4)+"px,0) rotateX("+(-y*.55)+"deg) rotateY("+(x*.75)+"deg)";
  floaters.forEach(function(item,i){item.style.translate=(x*(i%2?5:3))+"px "+(y*(i%2?4:2))+"px"});
 });
 frame.addEventListener("pointerleave",function(){card.style.transform="";floaters.forEach(function(item){item.style.translate=""})});
}
